import json
import os
from typing import List

from psycopg import sql

from src.models.generic_postgresql import GenericPostgresql


class EmbeddedPhrase(GenericPostgresql):
    # table columns:
    TABLE_NAME = "embedded_phrase"
    COL_ID = 'id'
    COL_PLATFORM = 'platform'
    COL_TENANT_ID = 'tenant_id'
    COL_LOCALE = 'locale'
    COL_STORE_CODE = 'store_code'
    COL_ATTRIBUTE_CODE = 'attribute_code'
    COL_ATTRIBUTE_VALUE_STRING = 'attribute_value_string'
    COL_ATTRIBUTE_VALUE_NUMBER = 'attribute_value_number'
    COL_PHRASE = 'phrase'
    COL_EMBEDDING = 'embedding'
    DEFAULT_RERANK_VERSION = 'rerank_v1'
    DEFAULT_RERANK_WEIGHTS = {
        'semantic': 0.80,
        'margin': 0.10,
        'business': 0.10,
    }

    def __init__(
        self,
        id: int = 0,
        platform: str = 'magento',
        tenant_id: str = 'default',
        locale: str = 'es_AR',
        store_code: str = 'default',
        attribute_code: str = '',
        attribute_value_string: str = '',
        attribute_value_number: int | float | None = None,
        phrase: str = '',
        embedding: List = []
    ):
        self.id = id
        self.platform = platform
        self.tenant_id = tenant_id
        self.locale = locale
        self.store_code = store_code
        self.attribute_code = attribute_code
        self.attribute_value_string = attribute_value_string
        self.attribute_value_number = attribute_value_number
        self.phrase = phrase
        self.embedding = embedding

    # TODO: this function may change, and use the class properties instead of receiving new params
    def insert_row(
            self,
            platform: str,
            tenant_id: str,
            locale: str,
            store_code: str,
            attribute_code: str,
            phrase: str,
            embedding: List,
            attribute_value_string: str = '',
            attribute_value_number: int | float | None = None,
    ) -> bool:
        if attribute_value_string != '':
            attribute_value_number = None

        insert_query = f"insert into {self.TABLE_NAME} ({self.COL_PLATFORM}, {self.COL_TENANT_ID}, {self.COL_LOCALE}, {self.COL_STORE_CODE}, {self.COL_ATTRIBUTE_CODE}, {self.COL_ATTRIBUTE_VALUE_STRING}, {self.COL_ATTRIBUTE_VALUE_NUMBER}, {self.COL_PHRASE}, {self.COL_EMBEDDING}) values(%s, %s, %s, %s, %s, %s, %s, %s, %s)"
        return self.insert_single_row(
            sql_query=insert_query,
            data=(platform, tenant_id, locale, store_code, attribute_code, attribute_value_string, attribute_value_number, phrase, embedding)
        )

    def select_row(
        self,
        embeddings: List[float],
        platform: str,
        tenant_id: str,
        locale: str,
        store_code: str,
        min_similarity: float = 0.30,
        top_k: int = 2,
        attribute_min_similarity: dict[str, float] | None = None,
    ) -> List:
        result = self.select_row_with_diagnostics(
            embeddings=embeddings,
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
            min_similarity=min_similarity,
            top_k=top_k,
            attribute_min_similarity=attribute_min_similarity,
        )
        return result["selected_filters"]

    def select_row_with_diagnostics(
        self,
        embeddings: List[float],
        platform: str,
        tenant_id: str,
        locale: str,
        store_code: str,
        min_similarity: float = 0.30,
        top_k: int = 2,
        attribute_min_similarity: dict[str, float] | None = None,
        query_text: str = '',
    ) -> dict:
        return self._select_row_for_scope(
            embeddings=embeddings,
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
            min_similarity=min_similarity,
            top_k=top_k,
            attribute_min_similarity=attribute_min_similarity,
            query_text=query_text,
        )

    def _select_row_for_scope(
        self,
        embeddings: List[float],
        platform: str,
        tenant_id: str,
        locale: str,
        store_code: str,
        min_similarity: float,
        top_k: int,
        attribute_min_similarity: dict[str, float] | None,
        query_text: str = '',
    ) -> dict:
        best_by_key = {}
        top_k = max(1, min(5, int(top_k)))
        rerank_cfg = self._load_rerank_config(
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
        )
        query_norm = self._normalize_phrase_text(query_text)
        query_client_suffix = self._extract_client_suffix(query_norm)

        dynamic_query = sql.SQL("""
            SELECT attribute_code, attribute_value_string, attribute_value_number, phrase, 1 - (embedding <=> %s::vector) AS similitud
            FROM {tabla}
            WHERE platform = %s
              AND tenant_id = %s
              AND locale = %s
              AND store_code = %s
            ORDER BY embedding <=> %s::vector
            LIMIT %s;
            """).format(tabla=sql.Identifier(self.TABLE_NAME))

        for item in embeddings:
            rows = self.execute_select(
                sql_query=dynamic_query,
                data=(item.tolist(), platform, tenant_id, locale, store_code, item.tolist(), top_k)
            )

            for row in rows:
                attribute_code = row[0]
                attribute_value_string = row[1] if row[1] is not None else ""
                attribute_value_number = row[2]
                phrase = row[3] if row[3] is not None else ""
                similarity = float(row[4]) if row[4] is not None else 0.0

                threshold = min_similarity
                if isinstance(attribute_min_similarity, dict):
                    threshold = float(attribute_min_similarity.get(attribute_code, min_similarity))

                if similarity < threshold:
                    continue

                key = f"{attribute_code}::{attribute_value_string}::{attribute_value_number}"
                prev = best_by_key.get(key)
                if prev is None or similarity > prev[4]:
                    best_by_key[key] = [
                        attribute_code,
                        attribute_value_string,
                        attribute_value_number,
                        phrase,
                        similarity,
                    ]

        candidates = list(best_by_key.values())

        by_attr = {}
        for row in candidates:
            attr = row[0]
            by_attr.setdefault(attr, []).append(row)

        selected_filters = []
        retrieval_attributes = []

        for attr, attr_rows in by_attr.items():
            has_numeric = any(r[2] is not None and str(r[2]) != "" for r in attr_rows)
            rows = attr_rows
            if has_numeric:
                rows = [r for r in attr_rows if r[2] is not None and str(r[2]) != ""]

            if query_norm != '':
                exact_phrase_rows = [
                    r for r in rows
                    if self._normalize_phrase_text(str(r[3] if r[3] is not None else '')) == query_norm
                ]
                if exact_phrase_rows:
                    rows = exact_phrase_rows
                elif query_client_suffix in ('b2c', 'b2b'):
                    client_rows = [
                        r for r in rows
                        if self._extract_client_suffix(self._normalize_phrase_text(str(r[3] if r[3] is not None else ''))) == query_client_suffix
                    ]
                    if client_rows:
                        rows = client_rows

            rows.sort(key=lambda r: float(r[4]), reverse=True)
            top_rows = rows[:top_k]
            if not top_rows:
                continue

            top_similarity = float(top_rows[0][4])
            second_similarity = float(top_rows[1][4]) if len(top_rows) > 1 else None

            scored_rows = []
            for row in top_rows:
                margin_component = (
                    max(float(row[4]) - second_similarity, 0.0)
                    if second_similarity is not None
                    else 0.0
                )

                business_boost = self._resolve_business_boost(
                    attribute_code=str(row[0]),
                    attribute_value_string=str(row[1] if row[1] is not None else ""),
                    attribute_value_number=row[2],
                    phrase=str(row[3] if row[3] is not None else ""),
                    boosts=rerank_cfg['business_boosts'],
                )

                final_score = (
                    rerank_cfg['weights']['semantic'] * float(row[4])
                    + rerank_cfg['weights']['margin'] * margin_component
                    + rerank_cfg['weights']['business'] * business_boost
                )

                scored_rows.append({
                    'row': row,
                    'margin_component': float(margin_component),
                    'business_boost': float(business_boost),
                    'final_score': float(final_score),
                })

            scored_rows.sort(key=lambda x: x['final_score'], reverse=True)

            selected_entry = scored_rows[0]
            selected = selected_entry['row']
            selected_filters.append([[selected[0], selected[1], selected[2], selected[3], selected[4]]])

            margin = (top_similarity - second_similarity) if second_similarity is not None else None

            if top_similarity >= 0.85 and (margin is None or margin >= 0.08):
                confidence_band = "high"
            elif top_similarity >= 0.65:
                confidence_band = "medium"
            else:
                confidence_band = "low"

            retrieval_attributes.append(
                {
                    "attribute_code": attr,
                    "selected": {
                        "attribute_code": selected[0],
                        "attribute_value_string": selected[1],
                        "attribute_value_number": selected[2],
                        "phrase": selected[3],
                        "similarity": float(selected[4]),
                        "final_score": float(selected_entry['final_score']),
                        "business_boost": float(selected_entry['business_boost']),
                    },
                    "top_k": [
                        {
                            "attribute_code": item['row'][0],
                            "attribute_value_string": item['row'][1],
                            "attribute_value_number": item['row'][2],
                            "phrase": item['row'][3],
                            "similarity": float(item['row'][4]),
                            "final_score": float(item['final_score']),
                            "business_boost": float(item['business_boost']),
                        }
                        for item in scored_rows
                    ],
                    "confidence": {
                        "top_similarity": top_similarity,
                        "second_similarity": second_similarity,
                        "margin": margin,
                        "confidence_band": confidence_band,
                    },
                    "rerank": {
                        "version": rerank_cfg['version'],
                        "selected_score": float(selected_entry['final_score']),
                        "selected_reason": (
                            f"semantic={float(selected[4]):.4f};"
                            f"margin={float(selected_entry['margin_component']):.4f};"
                            f"business={float(selected_entry['business_boost']):.4f}"
                        ),
                        "weights": {
                            "semantic": float(rerank_cfg['weights']['semantic']),
                            "margin": float(rerank_cfg['weights']['margin']),
                            "business": float(rerank_cfg['weights']['business']),
                        },
                    },
                }
            )

        return {
            "selected_filters": selected_filters,
            "retrieval": {
                "strategy": "top_k_per_attribute",
                "top_k": top_k,
                "min_similarity": float(min_similarity),
                "attributes": retrieval_attributes,
            },
        }

    def _normalize_phrase_text(self, text: str) -> str:
        tokens = self.normalizeTokens(text)
        return ' '.join(tokens)

    def _extract_client_suffix(self, text: str) -> str:
        normalized = text.strip().lower()
        if normalized.endswith(' b2c'):
            return 'b2c'
        if normalized.endswith(' b2b'):
            return 'b2b'
        return ''

    def _scope_part(self, value: str | None) -> str:
        text = "" if value is None else str(value).strip().lower()
        if text == "":
            return "DEFAULT"
        normalized = ''.join(ch if ch.isalnum() else '_' for ch in text)
        while '__' in normalized:
            normalized = normalized.replace('__', '_')
        normalized = normalized.strip('_')
        return normalized.upper() if normalized != "" else "DEFAULT"

    def _scoped_env_names(
        self,
        base: str,
        platform: str,
        tenant_id: str,
        locale: str,
        store_code: str,
    ) -> list[str]:
        p = self._scope_part(platform)
        t = self._scope_part(tenant_id)
        l = self._scope_part(locale)
        s = self._scope_part(store_code)

        # Broad -> specific, where later keys override earlier ones.
        return [
            f"{base}__{p}",
            f"{base}__{p}__{t}",
            f"{base}__{p}__{t}__{l}",
            f"{base}__{p}__{t}__{l}__{s}",
        ]

    def _load_rerank_config(
        self,
        platform: str,
        tenant_id: str,
        locale: str,
        store_code: str,
    ) -> dict:
        version = os.getenv('RETRIEVAL_RERANK_VERSION', self.DEFAULT_RERANK_VERSION).strip() or self.DEFAULT_RERANK_VERSION
        for env_name in self._scoped_env_names(
            base='RETRIEVAL_RERANK_VERSION',
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
        ):
            scoped_version = os.getenv(env_name, '').strip()
            if scoped_version != '':
                version = scoped_version

        weights = dict(self.DEFAULT_RERANK_WEIGHTS)
        raw_weights = os.getenv('RETRIEVAL_RERANK_WEIGHTS', '').strip()
        if raw_weights != '':
            try:
                parsed = json.loads(raw_weights)
                if isinstance(parsed, dict):
                    for key in ('semantic', 'margin', 'business'):
                        if key in parsed:
                            weights[key] = float(parsed[key])
            except Exception:
                pass

        for env_name in self._scoped_env_names(
            base='RETRIEVAL_RERANK_WEIGHTS',
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
        ):
            raw_scoped_weights = os.getenv(env_name, '').strip()
            if raw_scoped_weights == '':
                continue
            try:
                parsed = json.loads(raw_scoped_weights)
                if isinstance(parsed, dict):
                    for key in ('semantic', 'margin', 'business'):
                        if key in parsed:
                            weights[key] = float(parsed[key])
            except Exception:
                pass

        total = sum(max(v, 0.0) for v in weights.values())
        if total <= 0:
            weights = dict(self.DEFAULT_RERANK_WEIGHTS)
            total = sum(weights.values())
        weights = {k: max(v, 0.0) / total for k, v in weights.items()}

        boosts = {}
        raw_boosts = os.getenv('RETRIEVAL_BUSINESS_BOOSTS', '').strip()
        if raw_boosts != '':
            try:
                parsed = json.loads(raw_boosts)
                if isinstance(parsed, dict):
                    for key, value in parsed.items():
                        boosts[str(key).strip().lower()] = float(value)
            except Exception:
                pass

        for env_name in self._scoped_env_names(
            base='RETRIEVAL_BUSINESS_BOOSTS',
            platform=platform,
            tenant_id=tenant_id,
            locale=locale,
            store_code=store_code,
        ):
            raw_scoped_boosts = os.getenv(env_name, '').strip()
            if raw_scoped_boosts == '':
                continue
            try:
                parsed = json.loads(raw_scoped_boosts)
                if isinstance(parsed, dict):
                    for key, value in parsed.items():
                        boosts[str(key).strip().lower()] = float(value)
            except Exception:
                pass

        return {
            'version': version,
            'weights': weights,
            'business_boosts': boosts,
        }

    def _resolve_business_boost(
        self,
        attribute_code: str,
        attribute_value_string: str,
        attribute_value_number,
        phrase: str,
        boosts: dict,
    ) -> float:
        if not boosts:
            return 0.0

        attr = attribute_code.strip().lower()
        value_string = attribute_value_string.strip().lower()
        value_number = '' if attribute_value_number is None else str(attribute_value_number).strip().lower()
        phrase_l = phrase.strip().lower()

        keys = [
            f'{attr}::{value_number}' if value_number != '' else '',
            f'{attr}::{value_string}' if value_string != '' else '',
            f'phrase::{phrase_l}' if phrase_l != '' else '',
            f'attr::{attr}' if attr != '' else '',
        ]

        for key in keys:
            if key and key in boosts:
                return float(boosts[key])

        return 0.0
